popover:
export function FainanceInfoPopover({
  label,
  title,
  body,
  children,
  size,
  popupWidth,
  popupOffsetY,
  popupAlign,
  buttonStyle,
  popupStyle,
}: any) {
  var ctx = useApp();
  var dark = ctx.dark;
  var [open, setOpen] = useState(false);
  var [placement, setPlacement] = useState<any>(null);
  var theme = fainanceInfoTheme(dark);
  var buttonSize = size || 24;
  var popupBody = body != null ? body : children;
  var infoSurface = fainancePopupSurfaceStyle(dark, "info");
  var anchorRef = useRef<any>(null);
  var popupRef = useRef<any>(null);

  var reposition = useCallback(function () {
    if (!open || !anchorRef.current || typeof window === "undefined") return;
    var anchor = anchorRef.current.getBoundingClientRect();
    var vv: any = (window as any).visualViewport;
    var viewportLeft = vv && Number.isFinite(vv.offsetLeft) ? vv.offsetLeft : 0;
    var viewportTop = vv && Number.isFinite(vv.offsetTop) ? vv.offsetTop : 0;
    var viewportWidth = vv && Number.isFinite(vv.width) ? vv.width : window.innerWidth;
    var viewportHeight = vv && Number.isFinite(vv.height) ? vv.height : window.innerHeight;
    var viewportRight = viewportLeft + viewportWidth;
    var viewportBottom = viewportTop + viewportHeight;
    var margin = 10;
    var wantedWidth = Number(popupWidth || 320);
    if (!Number.isFinite(wantedWidth) || wantedWidth < 180) wantedWidth = 320;
    var width = Math.min(wantedWidth, Math.max(180, viewportWidth - margin * 2));

    var desiredLeft =
      popupAlign === "right"
        ? anchor.right - width
        : anchor.left;
    var left = Math.max(
      viewportLeft + margin,
      Math.min(desiredLeft, viewportRight - width - margin)
    );

    var measuredHeight =
      popupRef.current && popupRef.current.getBoundingClientRect
        ? popupRef.current.getBoundingClientRect().height
        : 0;
    var maxHeight = Math.max(120, viewportHeight - margin * 2);
    var popupHeight =
      measuredHeight > 0 ? Math.min(measuredHeight, maxHeight) : Math.min(220, maxHeight);
    var gap = Math.max(6, Number(popupOffsetY || buttonSize + 8) - buttonSize);
    var belowTop = anchor.bottom + gap;
    var aboveTop = anchor.top - gap - popupHeight;
    var roomBelow = viewportBottom - belowTop - margin;
    var roomAbove = anchor.top - viewportTop - gap - margin;
    var top =
      roomBelow >= popupHeight || roomBelow >= roomAbove
        ? belowTop
        : aboveTop;
    top = Math.max(
      viewportTop + margin,
      Math.min(top, viewportBottom - popupHeight - margin)
    );

    setPlacement({
      left: Math.round(left),
      top: Math.round(top),
      width: Math.round(width),
      maxHeight: Math.round(maxHeight),
    });
  }, [open, popupWidth, popupOffsetY, popupAlign, buttonSize]);

  useLayoutEffect(
    function () {
      if (!open) {
        setPlacement(null);
        return;
      }
      reposition();
      var raf1 = window.requestAnimationFrame(function () {
        reposition();
        window.requestAnimationFrame(reposition);
      });
      return function () {
        window.cancelAnimationFrame(raf1);
      };
    },
    [open, reposition, title, popupBody]
  );

  useEffect(
    function () {
      if (!open || typeof window === "undefined") return;
      function onViewportChange() {
        reposition();
      }
      window.addEventListener("resize", onViewportChange);
      window.addEventListener("orientationchange", onViewportChange);
      window.addEventListener("scroll", onViewportChange, true);
      var vv: any = (window as any).visualViewport;
      if (vv) {
        vv.addEventListener("resize", onViewportChange);
        vv.addEventListener("scroll", onViewportChange);
      }
      return function () {
        window.removeEventListener("resize", onViewportChange);
        window.removeEventListener("orientationchange", onViewportChange);
        window.removeEventListener("scroll", onViewportChange, true);
        if (vv) {
          vv.removeEventListener("resize", onViewportChange);
          vv.removeEventListener("scroll", onViewportChange);
        }
      };
    },
    [open, reposition]
  );

  useEffect(
    function () {
      if (!open || typeof document === "undefined") return;
      function closeOnOutside(event: any) {
        var target = event && event.target;
        if (anchorRef.current && anchorRef.current.contains(target)) return;
        if (popupRef.current && popupRef.current.contains(target)) return;
        setOpen(false);
      }
      document.addEventListener("pointerdown", closeOnOutside, true);
      return function () {
        document.removeEventListener("pointerdown", closeOnOutside, true);
      };
    },
    [open]
  );

  var popupNode =
    open && typeof document !== "undefined"
      ? createPortal(
          <div
            ref={popupRef}
            role="dialog"
            aria-label={title || label || "Informazioni"}
            style={{
              position: "fixed",
              left: placement ? placement.left : 10,
              top: placement ? placement.top : 10,
              width: placement ? placement.width : Math.min(Number(popupWidth || 320), 320),
              maxWidth: "calc(100vw - 20px)",
              maxHeight: placement ? placement.maxHeight : "calc(100dvh - 20px)",
              overflowY: "auto",
              overscrollBehavior: "contain",
              boxSizing: "border-box",
              padding: "11px 13px",
              fontSize: 12,
              lineHeight: 1.45,
              color: theme.popupText,
              zIndex: 2147483000,
              visibility: placement ? "visible" : "hidden",
              ...infoSurface,
              ...popupStyle,
            }}
          >
            {title && (
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 900,
                  color: theme.popupText,
                  marginBottom: popupBody ? 4 : 0,
                }}
              >
                {title}
              </div>
            )}
            {popupBody && (
              <div style={{ color: theme.popupSubtle }}>{popupBody}</div>
            )}
          </div>,
          document.body
        )
      : null;

  return (
    <>
      <div
        ref={anchorRef}
        style={{
          position: "relative",
          display: "inline-flex",
          alignItems: "center",
        }}
      >
        <button
          type="button"
          aria-label={label || title || "Informazioni"}
          title={label || title || "Informazioni"}
          aria-expanded={open}
          onClick={function () {
            setOpen(function (v) {
              return !v;
            });
          }}
          style={{
            width: buttonSize,
            height: buttonSize,
            borderRadius: "50%",
            border: "1px solid " + theme.buttonBorder,
            background: theme.buttonBg,
            color: theme.buttonText,
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: buttonSize <= 18 ? 11 : 13,
            fontWeight: 900,
            cursor: "pointer",
            boxShadow: dark ? "none" : "0 3px 10px rgba(194,157,31,0.16)",
            padding: 0,
            userSelect: "none",
            ...buttonStyle,
          }}
        >
          i
        </button>
      </div>
      {popupNode}
    </>
  );
}
